def read(path,limit=8388608):
    if path.resolve()!=path: raise ValueError("Symlink path refused")
    fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW)
    with os.fdopen(fd,"rb") as f:
        before=os.fstat(f.fileno())
        if not stat.S_ISREG(before.st_mode) or before.st_nlink!=1 or before.st_size>limit: raise ValueError("Read profile refused")
        raw=f.read(limit+1)
        after=os.fstat(f.fileno())
    if len(raw)>limit or (before.st_size,before.st_mtime_ns,before.st_ino)!=(after.st_size,after.st_mtime_ns,after.st_ino): raise ValueError("Changed read")
    return raw,{"path":str(path),"bytes":len(raw),"sha256":hashlib.sha256(raw).hexdigest()}
